using System;using System.Text;using UnityEditor;using UnityEngine;
namespace XuanwuTools { public static class RouteValidator {
 [MenuItem(Common.Menu+"02 Validate route JSON")] public static void Validate()=>Common.Run(()=>{var r=Common.Read<Route>();Common.SceneGuard(r.scenePath);Common.RouteCheck(r);Physics.SyncTransforms();int fail=0,count=0;var log=new StringBuilder();float width=Mathf.Max(0,r.halfWidth-r.radius);for(int j=1;j<r.points.Length;j++){Vector3 a=r.points[j-1],b=r.points[j],v=b-a;var lateral=Vector3.Cross(Vector3.up,new Vector3(v.x,0,v.z).normalized);int n=Mathf.CeilToInt(v.magnitude/r.step);if(n>5000)throw new Exception("Segment too long");for(int side=-1;side<=1;side++){float? last=null;for(int k=0;k<=n;k++){var p=Vector3.Lerp(a,b,k/(float)n)+lateral*(side*width);count++;string issue="";if(Common.Protected(p,r.protectedAreas))issue="protected area";else if(!Physics.Raycast(p+Vector3.up*r.castUp,Vector3.down,out RaycastHit hit,r.castUp+r.castDown,r.groundMask,QueryTriggerInteraction.Ignore))issue="no ground";else{float angle=Vector3.Angle(hit.normal,Vector3.up);if(angle>r.maxSlope)issue="slope "+angle;else if(last.HasValue&&Mathf.Abs(hit.point.y-last.Value)>r.maxStep)issue="height delta";else if(Physics.CheckCapsule(hit.point+Vector3.up*(r.radius+.05f),hit.point+Vector3.up*(r.height-r.radius+.05f),r.radius,r.obstacleMask,QueryTriggerInteraction.Ignore))issue="capsule obstruction";last=hit.point.y;}if(issue!=""){fail++;if(fail<=100)log.AppendLine($"segment={j} side={side} point={p} {issue}");}}}}Common.Report("route",$"samples={count}; failures={fail}; sampled geometry ONLY; controller/camera/roll/reverse playtest mandatory.\n"+log);});}}
